from pathlib import Path
import sys,json,re
root=Path(sys.argv[1])
edits=json.loads("{\"index.html\":{\"Waarmee kunnen wij u helpen?\":\"Specialistisch vloer- en betonwerk\",\"Is uw balkonvloer versleten of beschadigd? Bekijk wat er bij een nieuwe afwerking komt kijken.\":\"Herstel van beschadigde balkonvloeren en een nieuwe afwerking, met aandacht voor afwatering en aansluitingen.\",\"Scheuren of beschadigd beton? De juiste aanpak begint met het begrijpen van de oorzaak.\":\"Herstel van scheuren, afbrokkelende randen en andere betonschade, met aandacht voor de oorzaak.\",\"16 jaar praktijkervaring. Aandacht voor iedere afwerking.\":\"Kwaliteit begint vóór de afwerking.\",\"Bij JM Betonservice combineren we 16 jaar praktijkervaring met aandacht voor de ondergrond, voorbereiding en afwerking.\":\"Een strak eindresultaat begint bij een geschikte ondergrond. Met 16 jaar praktijkervaring kijken wij naar de staat van het beton, de benodigde voorbereiding en het gebruik van de ruimte. Zo weet u wat het werk inhoudt, ook waar u het later niet meer ziet.\",\"We bespreken uitvoering en kosten voordat u beslist.\":\"U krijgt duidelijkheid over de werkzaamheden en kosten voordat u beslist.\",\"Bekijk een selectie uit de eerdere werkzaamheden van JM Betonservice. De foto's laten verschillende vloeren en buitenoppervlakken zien.\":\"Bekijk onze werkfoto's: van afgewerkte woon- en bedrijfsvloeren tot balkons en de voorbereiding van de ondergrond.\"},\"over-ons/index.html\":{\"Met aandacht voor de bestaande ondergrond, het gebruik van de ruimte en een afwerking die bij het project past.\":\"Onze aandacht gaat niet alleen naar het eindresultaat, maar ook naar de voorbereiding waarop dat resultaat steunt.\",\"Geen enkele ruimte is precies hetzelfde. Een mooie afwerking begint daarom met de juiste vragen. Hoe wordt het oppervlak gebruikt? Wat is de huidige ondergrond? Zijn er bestaande beschadigingen of vochtproblemen? Die informatie helpt om samen te kijken welke werkzaamheden passend kunnen zijn.\":\"Een woonvloer vraagt een andere aanpak dan een werkplaats of een balkon. Wij kijken naar de staat van de ondergrond, eventuele schade en het dagelijks gebruik. Pas daarna adviseren we over de afwerking.\",\"We willen dat u begrijpt wat er wordt besproken. Ook als u niet precies weet welke vloer, coating of behandeling u nodig heeft, kunt u uw situatie gewoon aan ons voorleggen.\":\"U hoeft zelf geen vloerspecialist te zijn. Wij leggen uit welke voorbereiding nodig is, welke afwerkingen mogelijk zijn en welke keuzes invloed hebben op de kosten.\",\"Helder over de mogelijkheden\":\"Duidelijkheid over het werk\",\"We bespreken de mogelijkheden\":\"Advies over de aanpak\",\"We stemmen de vervolgstap af\":\"Een duidelijk vervolg\"},\"werkwijze/index.html\":{\"Vertel ons wat u wilt laten doen\":\"Uw project en wensen\",\"We bespreken de situatie\":\"Beoordeling van de situatie\",\"We bekijken mogelijke werkzaamheden\":\"Advies en voorbereiding\",\"Een passend voorstel als de opdracht duidelijk is\":\"Een duidelijk voorstel\",\"De precieze inhoud hangt af van de situatie, de benodigde voorbereiding en de gekozen werkzaamheden. We bespreken de uitvoering en de kosten voordat u beslist.\":\"De offerte draait om de benodigde werkzaamheden: van voorbereiding en herstel tot de gekozen afwerking. We bespreken de uitvoering en kosten vooraf, zodat u weet wat u kunt vergelijken.\"},\"diensten/gietvloeren/index.html\":{\"Een gietvloer wordt vloeibaar aangebracht en vormt na uitharding doorgaans een aaneengesloten vloeroppervlak. De juiste opbouw hangt af van uw ruimte, ondergrond en wensen.\":\"Een naadloze gietvloer geeft uw ruimte een rustige, strakke uitstraling. JM Betonservice adviseert over de juiste vloeropbouw, van voorbereiding van de ondergrond tot de uiteindelijke afwerking.\",\"Hoe verloopt het gesprek?\":\"Uw gietvloer op maat\",\"Vertel om welke ruimte het gaat en, als u dat weet, hoeveel vierkante meter u wilt laten aanpakken. Een foto van de bestaande vloer helpt om gerichte vragen te stellen. Daarna kunnen we bespreken welke mogelijkheden passend zijn.\":\"Geef de ruimte, geschatte oppervlakte en gewenste uitstraling door. Foto's van de bestaande vloer helpen ons bij het beoordelen van de voorbereiding. Op basis daarvan bespreken wij de afwerking en kosten.\",\"De oppervlakte, de bestaande ondergrond en de voorbereiding maken verschil. Bij herstelwerk speelt ook de aard van de schade mee. Beschrijf uw situatie voor een passend gesprek over de werkzaamheden en kosten.\":\"De prijs bestaat niet alleen uit de zichtbare afwerklaag. De oppervlakte, staat van de ondervloer, benodigde voorbereiding en keuze van het vloersysteem bepalen de werkzaamheden. Vraag een offerte aan op basis van uw eigen situatie.\"},\"diensten/betonreparatie/index.html\":{\"Scheuren, losse stukken of andere beschadigingen kunnen verschillende oorzaken hebben. Daarom is het verstandig de situatie eerst goed te beoordelen voordat een herstelmethode wordt gekozen.\":\"Scheuren, afbrokkelend beton en beschadigde randen verdienen een gerichte aanpak. JM Betonservice kijkt naar de aard en oorzaak van de schade voordat de herstelwerkzaamheden worden bepaald.\",\"Een goede aanvraag begint met informatie\":\"Gericht advies over betonschade\",\"De oppervlakte, de bestaande ondergrond en de voorbereiding maken verschil. Bij herstelwerk speelt ook de aard van de schade mee. Beschrijf uw situatie voor een passend gesprek over de werkzaamheden en kosten.\":\"De kosten van betonreparatie worden bepaald door de omvang en diepte van de schade, de bereikbaarheid en de noodzakelijke voorbereiding en herstelmethode. Stuur foto's voor een eerste beoordeling van uw aanvraag.\"},\"bedrijven/index.html\":{\"Van een werkplaats tot een bedrijfsruimte: een vloer moet passen bij wat er dagelijks gebeurt. JM Betonservice bespreekt de bestaande ondergrond, de gewenste afwerking en de praktische omstandigheden van uw project.\":\"Een bedrijfsvloer is onderdeel van uw dagelijkse bedrijfsvoering. JM Betonservice adviseert over vloerafwerking voor werkplaatsen, garages en bedrijfsruimtes, met aandacht voor belasting, onderhoud en planning.\",\"Wordt de ruimte dagelijks gebruikt door mensen, gereedschap of voertuigen? Beschrijf wat er op de vloer gebeurt. Zo kunnen wij de vereiste eigenschappen van de vloer beoordelen. Wilt u een nette, makkelijk te gebruiken garagevloer? Leg uit wat de ruimte moet kunnen verdragen, zodat het juiste systeem kan worden besproken.\":\"Bij een werkplaats of garage tellen voertuigbelasting, gereedschap, vuil en onderhoud. Wij adviseren over een vloerafwerking die aansluit op de werkelijke omstandigheden.\",\"Een werkplaats, garage of bedrijfshal vraagt om een vloer die past bij het dagelijks gebruik. Vertel ons welke ruimte u wilt laten aanpakken en wat er met de vloer gebeurt.\":\"Voor een bedrijfsruimte of magazijn zijn dagelijkse belasting, beschikbare werktijd en de staat van de ondergrond belangrijke uitgangspunten voor het vloeradvies.\",\"Wat vertelt u ons bij een zakelijke aanvraag?\":\"Een gerichte offerte voor uw bedrijfsruimte\"},\"contact/index.html\":{\"Vertel ons over uw klus\":\"Vraag uw offerte aan\",\"Vertel ons wat u wilt bereiken. Een korte omschrijving is genoeg om te beginnen.\":\"Een nieuwe vloer, balkonrenovatie of betonherstel? Beschrijf uw project. Wij helpen u bij het kiezen van de juiste aanpak.\",\"U hoeft niet precies te weten welk materiaal of welke behandeling nodig is. Vertel kort wat u wilt laten doen.\":\"Beschrijf de huidige situatie, uw wensen en indien bekend de oppervlakte. U hoeft zelf nog geen materiaal te kiezen.\",\"Zonder ingeschakelde formulierontvanger opent de aanvraag in WhatsApp. Geselecteerde foto’s worden daarbij niet automatisch meegestuurd; u voegt deze zelf toe.\":\"Uw aanvraag opent in WhatsApp. Voeg uw foto's daar toe voordat u het bericht verstuurt.\"}}")
total=0
for rel,pairs in edits.items():
    p=root/rel
    s=p.read_text(encoding="utf-8")
    for old,new in pairs.items():
        count=s.count(old)
        if not count:
            raise RuntimeError(f"Copy target missing: {rel}: {old[:70]}")
        s=s.replace(old,new)
        total+=count
    p.write_text(s,encoding="utf-8")
print(f"Premium positioning: {total} text replacements on {len(edits)} pages")
